/**
 * Genera múltiples nubes independientes y pequeñas con control directo sobre
 * el número de nubes, tamaño individual y forma orgánica.
 * 
 * @param {number} [originX=0] - Coordenada X base.
 * @param {number} [originY=0] - Coordenada Y base.
 * @param {number} [originZ=0] - Coordenada Z base.
 * @param {Object} [options] - Configuración.
 * @param {number} [options.mapWidth=100] - Ancho del mapa.
 * @param {number} [options.mapDepth=100] - Profundidad del mapa.
 * @param {number} [options.cloudAltitude=79] - Altura Y de las nubes.
 * @param {number} [options.cloudThickness=1] - Grosor de las nubes.
 * @param {number} [options.numClouds=7] - Cantidad de nubes independientes a generar.
 * @param {number} [options.minCloudSize=8] - Tamaño mínimo (radio aprox) de cada nube.
 * @param {number} [options.maxCloudSize=16] - Tamaño máximo (radio aprox) de cada nube.
 * @param {number} [options.margin=10] - Margen respecto a los bordes del mapa.
 * @param {string|number} [options.cloudMat='cubo_trans'] - Material.
 */
function buildHighFlatClouds(originX = 0, originY = 0, originZ = 0, options = {}) {
    const mapWidth = options.mapWidth || 100;
    const mapDepth = options.mapDepth || 100;
    const cloudAltitude = options.cloudAltitude || 79;
    const cloudThickness = options.cloudThickness || 1;

    const numClouds = options.numClouds || 7;
    const minCloudSize = options.minCloudSize || 8;
    const maxCloudSize = options.maxCloudSize || 16;
    const margin = options.margin !== undefined ? options.margin : 10;
    const cloudMat = options.cloudMat || 'cubo_trans';

    if (typeof beginBatch === 'function') beginBatch();

    // 1. LIMPIEZA PREVIA
    const maxClearHeight = cloudThickness + 1;
    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            for (let h = 0; h < maxClearHeight; h++) {
                const targetX = originX + x;
                const targetY = originY + cloudAltitude + h;
                const targetZ = originZ + z;

                if (typeof getVoxel !== 'function' || getVoxel(targetX, targetY, targetZ)) {
                    setVoxel(targetX, targetY, targetZ, 0);
                }
            }
        }
    }

    // Matriz 2D para registrar qué celdas contienen nubes
    const grid = Array.from({ length: mapWidth }, () => new Uint8Array(mapDepth));

    // 2. GENERACIÓN DE CÚMULOS INDEPENDIENTES
    for (let i = 0; i < numClouds; i++) {
        // Posición del centro del cúmulo respetando márgenes
        const cx = margin + Math.floor(Math.random() * (mapWidth - 2 * margin));
        const cz = margin + Math.floor(Math.random() * (mapDepth - 2 * margin));

        // Radio de esta nube en particular
        const rx = Math.floor(minCloudSize + Math.random() * (maxCloudSize - minCloudSize));
        const rz = Math.floor(minCloudSize + Math.random() * (maxCloudSize - minCloudSize));

        // Cada nube se forma uniendo de 2 a 4 sub-cúmulos superpuestos para dar variedad de forma
        const subClusters = 2 + Math.floor(Math.random() * 3);

        for (let sub = 0; sub < subClusters; sub++) {
            const subOffsetX = Math.floor((Math.random() - 0.5) * rx);
            const subOffsetZ = Math.floor((Math.random() - 0.5) * rz);
            const subRx = rx * (0.5 + Math.random() * 0.5);
            const subRz = rz * (0.5 + Math.random() * 0.5);

            const startX = Math.max(margin, Math.floor(cx + subOffsetX - subRx));
            const endX = Math.min(mapWidth - margin - 1, Math.ceil(cx + subOffsetX + subRx));
            const startZ = Math.max(margin, Math.floor(cz + subOffsetZ - subRz));
            const endZ = Math.min(mapDepth - margin - 1, Math.ceil(cz + subOffsetZ + subRz));

            for (let x = startX; x <= endX; x++) {
                for (let z = startZ; z <= endZ; z++) {
                    const dx = (x - (cx + subOffsetX)) / subRx;
                    const dz = (z - (cz + subOffsetZ)) / subRz;
                    const distSq = dx * dx + dz * dz;

                    // Ruido rápido en los bordes para romper la forma elíptica lisa
                    const edgeNoise = (Math.sin(x * 12.9898 + z * 78.233) * 43758.5453) % 1 * 0.25;

                    if (distSq + edgeNoise <= 1.0) {
                        grid[x][z] = 1;
                    }
                }
            }
        }
    }

    // 3. COLOCACIÓN DE VOXELS EN EL MUNDO
    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            if (grid[x][z] === 1) {
                for (let h = 0; h < cloudThickness; h++) {
                    setVoxel(originX + x, originY + cloudAltitude + h, originZ + z, cloudMat);
                }
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
}

buildHighFlatClouds(0, 0, 0, {
    cloudAltitude: 39,
    cloudThickness: 1,
    numClouds: 24,         // 6 nubes separadas
    minCloudSize: 5,      // Pequeñas (radio 5)
    maxCloudSize: 10,     // Hasta radio 10
    cloudMat: 'white_wool'
});
